int source[] = {1, 2, 3, 4};
int target[2]; // Capacity: 2 elements

// Range size: std::distance(source, source + 4) = 4

// Runtime Safety Context:
// std::copy requires that the destination starting at 'target'
// can hold exactly 4 elements.
// std::copy does NOT check destination boundary.
// If target capacity < 4 (UB potential):
std::copy(source, source + 4, target);

// Safe alternative if N elements are known:
// std::copy_n(source, 2, target);
